/**
 * Agent-tool emission (M3): one authored tool → one
 * `elementum_agent_*_tool` resource block, in ei's dialect. The owning
 * AGENT's to-tf drives the pass and supplies both back-references
 * (`agent_id`, `app_id`) — this module never names the agent or app
 * resource types.
 *
 * Reference dialect (verified live, docs/design/m3-agent-dialect.md):
 * - self-app target → the app's own resource ref;
 * - cross-app target → a name-keyed `data.elementum_app` lookup whose
 *   label derives from the app NAME (ei's sanitize rule);
 * - tool fields → a local field resource ref, or an object-scoped
 *   `data.elementum_field` lookup when the typed target is foreign.
 */
import { workspaceAspectKey } from "../../engine/build/context.js";
import { automationRunTargetResourceAttr } from "../automation/to-tf.js";
import { appScopedResourceLabel, expr, sanitizeName, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { fieldRefToTfValue } from "../field/to-tf.js";
import { encodeOptionalHandleDescription } from "../shared/handle-description.js";
import { TOOL_SUB_TYPE_BY_TYPE_KEY } from "./types.js";
function serviceAccountIdValue(token, where, ctx) {
    if (token.__kind !== "serviceAccount" || token.name === undefined || token.name === "") {
        ctx.diagnostics.push(`${where}: serviceAccount must be a serviceAccountRef({ app, name }); dropped`);
        return undefined;
    }
    if (token.appRefName !== ctx.appRefName) {
        ctx.diagnostics.push(`${where}: service account "${token.name}" belongs to app "${token.appRefName ?? ""}", not owning app "${ctx.appRefName}"; dropped`);
        return undefined;
    }
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, sanitizeName(token.name));
    if (ctx.serviceAccountRef === undefined) {
        ctx.diagnostics.push(`${where}: build context cannot materialize a service-account lookup; dropped`);
        return undefined;
    }
    return ctx.serviceAccountRef(tfLabel, token.name) ??
        expr.dataAttr("elementum_service_account", tfLabel, ["id"]);
}
/** authoring app/element token → its resolved target (workspace resource or foreign data ref). */
function resolveTarget(token, ctx) {
    // Legacy escape hatch (pre-#889): pull used to print an unresolved target
    // as a bare platform-id string cast (`"<uuid>" as any`) rather than
    // unsafePlatformId(...) — already-pulled workspaces still have this shape
    // on disk and must keep round-tripping directly as target_id.
    if (typeof token === "string") {
        return { value: token, refName: token, kind: "app" };
    }
    // Pull's escape hatch for a target export couldn't resolve to any
    // portable reference (#648) - the platform id round-trips directly as
    // target_id, no name/namespace data lookup needed or even possible.
    if (token.__unsafe === "platformId" && typeof token.value === "string" && token.value !== "") {
        return { value: token.value, refName: token.value, kind: "app" };
    }
    const refName = token.refName ?? "";
    const kind = token.__kind === "element" ? "element" : "app";
    if (kind === "app" && refName === ctx.appRefName) {
        return {
            value: expr.resourceAttr("elementum_app", ctx.appTfLabel, ["id"]),
            refName,
            kind,
            localTfLabel: ctx.appTfLabel,
        };
    }
    const sibling = ctx.workspaceAspects?.get(workspaceAspectKey(kind, refName));
    if (sibling !== undefined) {
        const resourceType = kind === "element" ? "elementum_element" : "elementum_app";
        return {
            value: expr.resourceAttr(resourceType, sibling.tfLabel, ["id"]),
            refName,
            kind,
            localTfLabel: sibling.tfLabel,
        };
    }
    // ei derives foreign-app/foreign-element data labels from the display NAME.
    const name = token.name ?? refName;
    const tfLabel = sanitizeName(token.namespace ?? name);
    // Board issue #42: an aspect token can be an element, not just an app —
    // must emit `data.elementum_element`, never `data.elementum_app`, or the
    // provider looks up the wrong resource type entirely.
    if (kind === "element") {
        ctx.foreignElementRef(tfLabel, name, token.namespace);
        return { value: expr.dataAttr("elementum_element", tfLabel, ["id"]), refName, kind, foreignTfLabel: tfLabel };
    }
    ctx.foreignAppRef(tfLabel, name, token.namespace);
    return { value: expr.dataAttr("elementum_app", tfLabel, ["id"]), refName, kind, foreignTfLabel: tfLabel };
}
/**
 * A field belonging to the tool's target aspect, when that target is
 * foreign to the tool's owning app — resolved via a `data.elementum_field`
 * lookup keyed by the TARGET's already-resolved id (never re-derived from
 * the field token's own `parentKind`/`parentName`, which would let a field
 * from some unrelated third aspect silently pair with this target's id;
 * see `resolveFieldForTarget`) + the field's display name. Same pattern as
 * `automation/to-tf.ts`'s `crossAppFieldToTf` and `field/to-tf.ts`'s
 * `resolveFieldOnObject`.
 */
function foreignTargetFieldRefValue(token, refName, target, ctx) {
    const fieldName = token.name ?? refName;
    const fieldLabel = `${target.kind}_${target.foreignTfLabel}_${tsLabelToTfLabel(refName)}`;
    ctx.foreignFieldRef("elementum_field", fieldLabel, target.value, fieldName);
    return expr.dataAttr("elementum_field", fieldLabel, ["id"]);
}
/**
 * authoring FieldRef token → the field resource address, resolved against
 * the tool's ACTUAL target aspect (`resolveTarget`'s result) — not just the
 * tool's owning app. A tool's fields are attributes of the record it
 * creates/searches/updates, so a field whose `parent` doesn't match the
 * target (by refName AND kind — an app and a foreign element can share a
 * refName) is an authoring error the platform would otherwise reject
 * opaquely at apply ("field is not valid on target aspect"); `target`
 * absent (defensive: only possible for `searchTable`'s optional-aspect
 * shape, which doesn't use this field path) falls back to the tool's own
 * app as before.
 */
function fieldRefValue(token, where, ctx, target) {
    const refName = token.refName ?? "";
    if (refName === "") {
        ctx.diagnostics.push(`${where}: field token has no refName; dropped`);
        return undefined;
    }
    if (target !== undefined) {
        // `parentKind` is stamped ALONGSIDE a FOREIGN `parent` by `appCatalog`/
        // `elementCatalog` (see `FieldRef`'s doc comment) — but a field's own
        // `.ref()` on ITS OWN app/element stamps `parent` (as a self-reference)
        // without `parentKind` at all (a real, common shape — see e.g.
        // `__tests__/extract/update-record-tool.test.ts`'s fixture literals), so
        // only a parent naming something OTHER than the tool's owning app is
        // genuinely ambiguous. Defaulting `parentKind` to "app" THERE instead of
        // failing loudly is the same silent-miss failure mode
        // `automation/to-tf.ts`'s `crossAppFieldToTf` guards against: an element
        // field with a missing kind stamp would validate (and later resolve) as
        // if it belonged to an app of the same refName.
        if (token.parent !== undefined && token.parent !== ctx.appRefName && token.parentKind === undefined) {
            ctx.diagnostics.push(`${where}: field "${refName}" has a parent ("${token.parent}") but no parentKind — incomplete foreign-field provenance; dropped`);
            return undefined;
        }
        const parent = token.parent ?? ctx.appRefName;
        const parentKind = token.parentKind ?? "app";
        if (parent !== target.refName || parentKind !== target.kind) {
            ctx.diagnostics.push(`${where}: field "${refName}" belongs to ${parentKind} "${parent}", not the tool's target ${target.kind} "${target.refName}" — a tool's fields must belong to its own target aspect; dropped`);
            return undefined;
        }
        if (target.localTfLabel === undefined)
            return foreignTargetFieldRefValue(token, refName, target, ctx);
        // Falls through to the local resource-address resolution below.
    }
    else if (token.parent !== undefined && (token.parent !== ctx.appRefName || token.parentKind === "element")) {
        ctx.diagnostics.push(`${where}: field "${refName}" belongs to "${token.parent}", not this tool's app; dropped`);
        return undefined;
    }
    // Delegates to field/to-tf.ts's shared resolver (system-field local alias
    // vs. real field resource, by authoring type) rather than reimplementing
    // it here — see fieldRefToTfValue's doc comment for the system-field
    // ordering rationale.
    const value = fieldRefToTfValue(token.fieldType ?? "", refName, target?.localTfLabel ?? ctx.appTfLabel, target?.kind ?? "app");
    if (value === undefined) {
        ctx.diagnostics.push(`${where}: field token "${refName}" has no terraform field resource mapping (fieldType ${JSON.stringify(token.fieldType ?? "")}); dropped`);
    }
    return value;
}
/**
 * One authored tool entry (`{ createRecord: {...} }`) → its resource block;
 * undefined = degraded with a diagnostic (unimplemented sub-type, missing
 * target). The one hard error is an invalid tool name — the platform would
 * reject it at apply with an opaque message, so fail at build time instead.
 */
export function toolToTf(entry, ctx) {
    const typeKey = Object.keys(entry)[0];
    if (typeKey === undefined)
        return undefined;
    const subType = TOOL_SUB_TYPE_BY_TYPE_KEY.get(typeKey);
    const inner = entry[typeKey];
    const name = inner?.name ?? "";
    if (subType === undefined) {
        ctx.diagnostics.push(`agent tool "${name}": unknown tool kind "${typeKey}"; dropped`);
        return undefined;
    }
    if (subType.implemented !== true) {
        ctx.diagnostics.push(`agent tool "${name}": tool kind "${typeKey}" is not supported on the terraform path yet; dropped`);
        return undefined;
    }
    if (inner === undefined || typeof inner !== "object") {
        ctx.diagnostics.push(`agent tool entry "${typeKey}" has a non-object body; dropped`);
        return undefined;
    }
    const where = `agent tool "${name}"`;
    const agentTfLabel = appScopedResourceLabel(ctx.appTfLabel, ctx.agentBareTfLabel);
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, sanitizeName(`${ctx.agentBareTfLabel}_${name}`));
    const attrs = {
        agent_id: expr.resourceAttr("elementum_agent", agentTfLabel, ["id"]),
        app_id: expr.resourceAttr("elementum_app", ctx.appTfLabel, ["id"]),
        name,
        description: inner.description ?? "",
    };
    if (inner.startMessage !== undefined)
        attrs["start_message"] = inner.startMessage;
    const runAs = inner.runAs;
    if (runAs?.["currentUser"] === true) {
        attrs["run_as"] = "current_user";
    }
    else if (runAs?.["publisher"] === true) {
        attrs["run_as"] = "publisher";
    }
    else if (runAs?.["serviceAccount"] !== undefined) {
        const serviceAccountId = serviceAccountIdValue(runAs["serviceAccount"], where, ctx);
        if (serviceAccountId !== undefined) {
            attrs["run_as"] = "service_account";
            attrs["service_account_id"] = serviceAccountId;
        }
    }
    else if (runAs !== undefined) {
        ctx.diagnostics.push(`${where}: runAs ${JSON.stringify(runAs)} is not supported; dropped`);
    }
    if (typeKey === "executeWorkflow") {
        const auto = inner.automationId;
        // Identity is the token's refName (the bag key — its tfLabel image IS the
        // automation's label, per the bijection); the display name is a fallback
        // for hand-written tokens. Generated catalog tokens carry no name.
        const autoTfLabel = typeof auto?.refName === "string" && auto.refName !== ""
            ? tsLabelToTfLabel(auto.refName)
            : typeof auto?.name === "string" && auto.name !== ""
                ? sanitizeName(auto.name)
                : undefined;
        if (auto === undefined || autoTfLabel === undefined) {
            ctx.diagnostics.push(`${where}: no target automation token; dropped`);
            return undefined;
        }
        if (auto.parent !== undefined && auto.parent !== ctx.appRefName) {
            if (auto.parentKind === undefined || auto.parentName === undefined) {
                ctx.diagnostics.push(`${where}: foreign automation has incomplete owner identity; dropped`);
                return undefined;
            }
            const dataLabel = `${auto.parentKind}_${tsLabelToTfLabel(auto.parent)}_${autoTfLabel}`;
            if (ctx.foreignAutomationRef === undefined) {
                ctx.diagnostics.push(`${where}: foreign automation lookup registry is unavailable; dropped`);
                return undefined;
            }
            ctx.foreignAutomationRef(dataLabel, auto.name ?? auto.refName ?? "", {
                kind: auto.parentKind,
                refName: auto.parent,
                name: auto.parentName,
                ...(auto.parentNamespace !== undefined ? { namespace: auto.parentNamespace } : {}),
            });
            attrs["automation_id"] = expr.dataAttr("elementum_automation", dataLabel, ["id"]);
        }
        else {
            attrs["automation_id"] = automationRunTargetResourceAttr(ctx.appTfLabel, typeof auto?.refName === "string" && auto.refName !== "" ? auto.refName : autoTfLabel, ctx.activeAutomationRefNames);
        }
        if (inner.inputs !== undefined && inner.inputs.length > 0) {
            attrs["inputs"] = inner.inputs.map((i) => ({
                parameter_name: i.triggerParameterId?.name ?? "",
                ...(i.description !== undefined && i.description !== "" && { description: i.description }),
                ...(i.required !== undefined && { required: i.required }),
            }));
        }
        if (inner.outputs !== undefined && inner.outputs.length > 0) {
            attrs["outputs"] = inner.outputs.map((o) => ({
                workflow_property_name: o.workflowPropertyName ?? "",
                ...(o.description !== undefined && o.description !== "" && { description: o.description }),
            }));
        }
        // Write-only on the backend (no read resolver): ei exports the provider
        // schema default statically, and a fresh import seeds the same — any
        // other value would plan an eternal diff. Pinned, not authorable.
        attrs["timeout"] = "PT5M";
        const block = { kind: "resource", type: subType.resourceType, label: tfLabel, attrs };
        return { block, address: `${subType.resourceType}.${tfLabel}` };
    }
    if (typeKey === "runAgent") {
        const target = inner.targetAgentId;
        const targetRefName = target?.refName ?? "";
        if (target === undefined || targetRefName === "") {
            ctx.diagnostics.push(`${where}: no target agent token; dropped`);
            return undefined;
        }
        if (target.parent !== undefined && target.parent !== ctx.appRefName) {
            ctx.diagnostics.push(`${where}: target agent "${targetRefName}" belongs to app "${target.parent}" — cross-app run-agent tools are not supported on the terraform path yet; dropped`);
            return undefined;
        }
        attrs["target_agent_id"] = expr.resourceAttr("elementum_agent", appScopedResourceLabel(ctx.appTfLabel, tsLabelToTfLabel(targetRefName)), ["id"]);
        attrs["worker_task_prompt"] = inner.workerTaskPrompt ?? "";
        const block = { kind: "resource", type: subType.resourceType, label: tfLabel, attrs };
        return { block, address: `${subType.resourceType}.${tfLabel}` };
    }
    if (typeKey === "mcp") {
        if (inner.serverUrl === undefined || inner.serverUrl === "") {
            ctx.diagnostics.push(`${where}: no serverUrl; dropped`);
            return undefined;
        }
        if (inner.mcpToolName === undefined || inner.mcpToolName === "") {
            ctx.diagnostics.push(`${where}: no mcpToolName; dropped`);
            return undefined;
        }
        attrs["server_url"] = inner.serverUrl;
        attrs["mcp_tool_name"] = inner.mcpToolName;
        if (inner.headers !== undefined && inner.headers.length > 0) {
            attrs["headers"] = inner.headers.map((header) => ({
                key: header.key ?? "",
                value: header.value ?? "",
            }));
        }
        const block = { kind: "resource", type: subType.resourceType, label: tfLabel, attrs };
        return { block, address: `${subType.resourceType}.${tfLabel}` };
    }
    // searchTable is the one sub-type where a target aspect is optional
    // (confirmed live — see toolFromTf's matching comment).
    if (inner.aspectId === undefined && typeKey !== "searchTable") {
        ctx.diagnostics.push(`${where}: no target aspect token; dropped`);
        return undefined;
    }
    const target = inner.aspectId !== undefined ? resolveTarget(inner.aspectId, ctx) : undefined;
    if (target !== undefined)
        attrs["target_id"] = target.value;
    if (typeKey === "relateRecord") {
        if (inner.relatedAspectId === undefined) {
            ctx.diagnostics.push(`${where}: no related aspect token; dropped`);
            return undefined;
        }
        attrs["related_target_id"] = resolveTarget(inner.relatedAspectId, ctx).value;
    }
    if (typeKey === "updateRecord") {
        encodeOptionalHandleDescription(attrs, inner.handleDescription);
    }
    if (typeKey === "searchAspect" || typeKey === "searchTable") {
        attrs["query_description"] = inner.queryDescription ?? "";
        if (inner.limit !== undefined)
            attrs["result_limit"] = inner.limit;
        if (inner.filter !== undefined || inner.sort !== undefined) {
            ctx.diagnostics.push(`${where}: filter/sort are not supported on the terraform path yet; dropped`);
        }
    }
    if ((typeKey === "searchAspect" || typeKey === "searchTable") && inner.filterVariables !== undefined && inner.filterVariables.length > 0) {
        attrs["filter_variables"] = inner.filterVariables.map((variable) => ({
            id: typeof variable.id === "string" ? variable.id : variable.id?.value ?? "",
            name: variable.name ?? "",
            description: variable.description ?? "",
            required: variable.required ?? false,
        }));
    }
    if (typeKey === "searchTable") {
        const table = inner.searchTableId;
        if (table?.refName === undefined || table.refName === "") {
            ctx.diagnostics.push(`${where}: no search table token; dropped`);
            return undefined;
        }
        if (target !== undefined && table.parent !== undefined && table.parent !== "" && table.parent !== target.refName) {
            ctx.diagnostics.push(`${where}: search table belongs to "${table.parent}", not target "${target.refName}"; dropped`);
            return undefined;
        }
        if (target?.localTfLabel !== undefined) {
            const resourceType = table.__variant === "linked"
                ? "elementum_linked_ai_search_table"
                : table.__variant === "table"
                    ? "elementum_table_search_table"
                    : "elementum_ai_search_table";
            attrs["search_table_id"] = expr.resourceAttr(resourceType, scopedResourceLabel(target.localTfLabel, tsLabelToTfLabel(table.refName), target.kind), ["id"]);
        }
        else if (target !== undefined) {
            const lookupLabel = sanitizeName(`${target.foreignTfLabel}_${table.name ?? table.refName}`);
            ctx.foreignFieldRef("elementum_search_table", lookupLabel, target.value, table.name ?? table.refName);
            attrs["search_table_id"] = expr.dataAttr("elementum_search_table", lookupLabel, ["id"]);
        }
        else {
            ctx.diagnostics.push(`${where}: search table has no target aspect; dropped`);
            return undefined;
        }
    }
    if (inner.fields !== undefined && inner.fields.length > 0) {
        const fieldValues = [];
        for (const f of inner.fields) {
            // A raw-id fallback field (board issue #169) is echoed straight
            // through — ei never resolves it to a reference either, so there's
            // nothing to re-derive.
            const ref = typeof f.fieldId === "string"
                ? f.fieldId
                : f.fieldId === undefined
                    ? undefined
                    : fieldRefValue(f.fieldId, where, ctx, target);
            if (ref === undefined)
                continue;
            fieldValues.push({
                field_id: ref,
                // The wire duplicates the display name; the dialect carries one.
                ...(f.name !== undefined && { name: f.name }),
                ...(f.description !== undefined && { description: f.description }),
                // Always emit `required` (defaulting false) rather than omitting it:
                // the provider's own Create/Read round trip normalizes a missing
                // value to `false` and returns it, so a config that omits the key
                // plans an eternal `required: false -> null` diff on every apply
                // after the first (confirmed live 2026-08-05). Pin it, like
                // executeWorkflow's `timeout`, so config and state agree.
                required: f.required ?? false,
                ...(f.defaultValue !== undefined && { default_value: f.defaultValue }),
            });
        }
        if (fieldValues.length > 0)
            attrs["fields"] = fieldValues;
    }
    // Search-table fields use the same target-owned FieldRef resolution as
    // other agent tools while preserving their distinct provider dialect.
    if (inner.searchTableFields !== undefined && inner.searchTableFields.length > 0) {
        const values = [];
        for (const f of inner.searchTableFields) {
            const ref = typeof f.fieldId === "string"
                ? f.fieldId
                : f.fieldId === undefined
                    ? undefined
                    : fieldRefValue(f.fieldId, where, ctx, target);
            if (ref === undefined || ref === "") {
                ctx.diagnostics.push(`${where}: fields item has no fieldId; dropped`);
                continue;
            }
            values.push({
                field_id: ref,
                ...(f.name !== undefined && { name: f.name }),
                ...(f.description !== undefined && { description: f.description }),
            });
        }
        if (values.length > 0)
            attrs["fields"] = values;
    }
    if (inner.returnFields !== undefined && inner.returnFields.length > 0) {
        const returnFieldValues = [];
        for (const f of inner.returnFields) {
            const ref = typeof f.fieldId === "string"
                ? f.fieldId
                : f.fieldId === undefined
                    ? undefined
                    : fieldRefValue(f.fieldId, where, ctx, target);
            if (ref === undefined || ref === "") {
                ctx.diagnostics.push(`${where}: return_fields item has no fieldId; dropped`);
                continue;
            }
            returnFieldValues.push({
                field_id: ref,
                ...(f.name !== undefined && { name: f.name }),
                ...(f.displayName !== undefined && { display_name: f.displayName }),
            });
        }
        if (returnFieldValues.length > 0)
            attrs["return_fields"] = returnFieldValues;
    }
    const block = { kind: "resource", type: subType.resourceType, label: tfLabel, attrs };
    return { block, address: `${subType.resourceType}.${tfLabel}` };
}
